sockaddr_in peer{};
socklen_t len = sizeof peer;
int conn = accept(listen_fd, reinterpret_cast<sockaddr*>(&peer), &len);
if (conn == -1 && errno == EINTR) continue;

sockaddr_in srv{};
srv.sin_family = AF_INET;
srv.sin_port = htons(8080);
inet_pton(AF_INET, "127.0.0.1", &srv.sin_addr);
if (connect(fd, reinterpret_cast<sockaddr*>(&srv), sizeof srv) == -1) perror("connect");

const char *msg = "hello\n";
ssize_t n = send(conn, msg, strlen(msg), MSG_NOSIGNAL);
if (n == -1) perror("send");

char buf[1024];
ssize_t n = recv(conn, buf, sizeof buf - 1, 0);
if (n > 0) { buf[n] = '\0'; std::printf("%s", buf); }
else if (n == 0) { /* 对端关闭 */ }

ssize_t n = read(conn, buf, sizeof buf);
if (n == 0) { /* 对端关闭 */ }
else if (n < 0 && errno != EINTR) { perror("read"); }

shutdown(conn, SHUT_WR);   // 告诉对端我不再发了
// 仍可 recv 对端剩余数据
close(conn);

int one = 1;
